/// Mocktail gateway mock (the documented "mock a function" recipe): the
/// persistence step of [ChatStore] is a `Future<bool> Function(ChatMessage)`
/// tear-off, so the mock mocks a `call` method.
class _MockInsertGateway extends Mock {
  Future<bool> call(ChatMessage message) => super.noSuchMethod(
        Invocation.method(#call, [message]),
      );
}

/// Mocktail mock for the media-upload seam: mirrors the
/// `(requestId, file, kind) → public URL?` signature of
/// [ChatStore.uploadMediaGateway] so tests can simulate a Storage upload
/// without touching the network.
class _MockUploadGateway extends Mock {
  Future<String?> call(String requestId, File file, String kind) =>
      super.noSuchMethod(
        Invocation.method(#call, [requestId, file, kind]),
      );
}

