â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬
  group('sending (happy path)', () {
    test('send() appends the bubble IMMEDIATELY, before the backend answers',
        () async {
      final persister = _MockInsertGateway();
      ChatStore.insertMessageGateway = persister.call;
      // Hold the INSERT in flight: the optimistic append must already be
      // visible to the UI while the transport is still undecided.
      final inFlight = Completer<void>();
      when(() => persister.call(any()))
          .thenAnswer((_) => inFlight.future.then((_) => true));

      await _openChat('req-1');
      ChatStore.send(
        requestId: 'req-1',
        senderId: 'client-uuid',
        senderName: 'Feres',
        text: 'salam',
        isCustomer: true,
      );

      final bubbles = ChatStore.forRequest('req-1');
      expect(bubbles, hasLength(1), reason: 'optimistic UI update');
      expect(bubbles.first.text, 'salam');
      expect(bubbles.first.senderId, 'client-uuid');
      expect(bubbles.first.isCustomer, isTrue);
      expect(bubbles.first.type, ChatMessageType.text);
      expect(ChatStore.isDeliveryFailed(bubbles.first.id), isFalse);

      // The gateway was called exactly once, carrying the SAME message the
      // bubble shows (same id ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ realtime dedupe stays 1:1).
      final captured = verify(() => persister.call(captureAny()))
          .captured
          .single as ChatMessage;
      expect(captured.id, bubbles.first.id);
      expect(captured.text, 'salam');

      // Settle the in-flight insert: no duplicate bubble, flag stays clear.
      inFlight.complete();
      await Future<void>.delayed(Duration.zero);
      expect(ChatStore.forRequest('req-1'), hasLength(1));
      expect(ChatStore.isDeliveryFailed(bubbles.first.id), isFalse);
    });

    test('voice/location sends carry their media metadata optimistically',
        () async {
      final persister = _MockInsertGateway();
      ChatStore.insertMessageGateway = persister.call;
      when(() => persister.call(any())).thenAnswer((_) async => true);
      // Offline media path: the Storage upload is unreachable in unit tests
      // (no Supabase client, no network) → null → the voice bubble stays
      // local-first and flagged until a retry/echo reconciles it.
      ChatStore.uploadMediaGateway = (_, __, ___) async => null;

      await _openChat('req-media');
      ChatStore.sendVoice(
        requestId: 'req-media',
        senderId: 'pro-1',
        senderName: 'Sami',
        filePath: '/data/user/0/voice/note.m4a',
        durationSec: 12,
        isCustomer: false,
      );
      ChatStore.sendLocation(
        requestId: 'req-media',
        senderId: 'pro-1',
        senderName: 'Sami',
        latitude: 36.8,
        longitude: 10.18,
        isCustomer: false,
      );

      final bubbles = ChatStore.forRequest('req-media');
      expect(bubbles, hasLength(2));
      // LOCAL MEDIA (design): a device path is uploaded through
      // [ChatStore.uploadMediaGateway] before the row is mirrored — the voice
      // bubble is flagged undelivered until the upload lands; the location
      // (remote-safe) lands immediately.
      await Future<void>.delayed(Duration.zero);
      expect(ChatStore.isDeliveryFailed(bubbles[0].id), isTrue);
      expect(ChatStore.isDeliveryFailed(bubbles[1].id), isFalse);
      expect(bubbles[0].isVoice, isTrue);
      expect(bubbles[0].voiceDurationSec, 12);
      expect(bubbles[1].isLocation, isTrue);
      expect(bubbles[1].latitude, 36.8);
      verify(() => persister.call(any())).called(1);
    });
  });

