Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬
  group('realtime receiving', () {
    test(
        'applyRemoteMessage appends the incoming message and notifies the '
        'receiving party', () {
      RequestStore.requests.value = [_request(id: 'req-2')];
      ChatStore.activate('req-2');
      final idsBefore =
          NotificationStore.notifications.value.map((n) => n.id).toSet();

      ChatStore.applyRemoteMessage(ChatMessage(
        id: 'remote-1',
        requestId: 'req-2',
        senderId: 'pro-1',
        senderName: 'Sami',
        text: 'salam',
        sentAt: DateTime(2026),
        isCustomer: false,
      ));

      final bubbles = ChatStore.forRequest('req-2');
      expect(bubbles, hasLength(1));
      expect(bubbles.first.id, 'remote-1');
      expect(bubbles.first.text, 'salam');

      // The receiving party (the customer) is notified exactly once.
      final chatNotifs = NotificationStore.notifications.value
          .where((n) => !idsBefore.contains(n.id))
          .where((n) => n.message.contains('Sami'))
          .toList();
      expect(chatNotifs, hasLength(1));
    });

    test('the realtime echo of a locally-sent message is deduplicated by id',
        () async {
      await _openChat('req-echo');
      ChatStore.insertMessageGateway = (message) async => true;

      ChatStore.send(
        requestId: 'req-echo',
        senderId: 'client-uuid',
        senderName: 'Feres',
        text: 'salam',
        isCustomer: true,
      );
      final local = ChatStore.forRequest('req-echo').single;

      // The sender's own device ALSO receives its INSERT through the channel:
      // the row carries the same primary key ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ dedupe must keep ONE bubble.
      final echo = ChatMessage(
        id: local.id,
        requestId: 'req-echo',
        senderId: 'client-uuid',
        senderName: 'Feres',
        text: 'salam',
        sentAt: DateTime(2026),
        isCustomer: true,
      );
      ChatStore.applyRemoteMessage(echo);

      expect(ChatStore.forRequest('req-echo'), hasLength(1));
      // Echo = backend delivery confirmation: even if the bubble had been
      // flagged undelivered (failure raced the echo), the stale flag is
      // cleared and a stale retry becomes a harmless no-op.
      expect(ChatStore.isDeliveryFailed(local.id), isFalse);
      expect(await ChatStore.retryDelivery(local.id), isTrue);
    });

    test('a realtime echo clears a stale undelivered flag (failure raced echo)',
        () async {
      await _openChat('req-echo-stale');
      ChatStore.insertMessageGateway = (message) async => true;

      ChatStore.send(
        requestId: 'req-echo-stale',
        senderId: 'client-uuid',
        senderName: 'Feres',
        text: 'salam',
        isCustomer: true,
      );
      final local = ChatStore.forRequest('req-echo-stale').single;

      // Simulate the race: the mirror failed (or is still in flight) and the
      // bubble was flagged, THEN the backend echo lands through realtime.
      // Direct gateway access keeps the test synchronous and deterministic.
      ChatStore.debugMarkUndeliveredForTest(local.id);
      expect(ChatStore.isDeliveryFailed(local.id), isTrue);

      ChatStore.applyRemoteMessage(ChatMessage(
        id: local.id,
        requestId: 'req-echo-stale',
        senderId: 'client-uuid',
        senderName: 'Feres',
        text: 'salam',
        sentAt: DateTime(2026),
        isCustomer: true,
      ));

      expect(ChatStore.forRequest('req-echo-stale'), hasLength(1));
      expect(ChatStore.isDeliveryFailed(local.id), isFalse);
      expect(await ChatStore.retryDelivery(local.id), isTrue);
    });

    test('a realtime echo upgrades a local media path to the remote URL',
        () async {
      await _openChat('req-echo-media');
      ChatStore.insertMessageGateway = (message) async => true;

      ChatStore.sendVoice(
        requestId: 'req-echo-media',
        senderId: 'client-uuid',
        senderName: 'Feres',
        filePath: '/data/user/0/voice/note.m4a',
        durationSec: 7,
        isCustomer: true,
      );
      final local = ChatStore.forRequest('req-echo-media').single;
      expect(local.mediaPath, '/data/user/0/voice/note.m4a');

      // The backend echo carries the canonical Storage URL (upload finished on
      // the sender side / another device): the local bubble is reconciled in
      // place, still exactly one bubble, with no notification for our echo.
      const remoteUrl = 'https://cdn.example/req-echo-media/voice_1.m4a';
      ChatStore.applyRemoteMessage(ChatMessage(
        id: local.id,
        requestId: 'req-echo-media',
        senderId: 'client-uuid',
        senderName: 'Feres',
        text: '',
        sentAt: DateTime(2026),
        isCustomer: true,
        type: ChatMessageType.voice,
        mediaPath: remoteUrl,
        voiceDurationSec: 7,
      ));

      final bubbles = ChatStore.forRequest('req-echo-media');
      expect(bubbles, hasLength(1));
      expect(bubbles.single.mediaPath, remoteUrl);
      expect(ChatStore.isDeliveryFailed(local.id), isFalse);
    });

    test('a message authored by the LOCAL identity never notifies itself', () {
      UserStore.user.value = const UserModel(
        id: 'pro-1',
        name: 'Sami',
        phone: '',
        role: UserRole.professional,
      );
      RequestStore.requests.value = [_request(id: 'req-self')];
      ChatStore.activate('req-self');
      final notifsBefore = NotificationStore.notifications.value.length;

      // Authored by the local identity but arriving through realtime (the
      // user's OTHER device): appended, yet silent.
      ChatStore.applyRemoteMessage(ChatMessage(
        id: 'self-echo-1',
        requestId: 'req-self',
        senderId: 'pro-1',
        senderName: 'Sami',
        text: 'salam',
        sentAt: DateTime(2026),
        isCustomer: false,
      ));

      expect(ChatStore.forRequest('req-self'), hasLength(1));
      expect(NotificationStore.notifications.value.length, notifsBefore);
    });
  });

  // ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ 3. ERROR HANDLING ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â transport failure / backend refusal ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬
  group('error handling while sending', () {
    test(
        'a network failure keeps the bubble local-first, flags it for retry, '
        'and never crashes the fire-and-forget caller', () async {
      final persister = _MockInsertGateway();
      ChatStore.insertMessageGateway = persister.call;
      when(() => persister.call(any()))
          .thenThrow(const SocketException('device offline'));

      await _openChat('req-err');
      expect(
        () => ChatStore.send(
          requestId: 'req-err',
          senderId: 'client-uuid',
          senderName: 'Feres',
          text: 'salam',
          isCustomer: true,
        ),
        returnsNormally,
        reason:
            'the mirror is fire-and-forget ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â a transport error must never '
            'propagate into the send path',
      );

      // Local-first: the bubble survives the failure (zero data loss).
      final bubbles = ChatStore.forRequest('req-err');
      expect(bubbles, hasLength(1));

      // The failure is OBSERVABLE state (retry affordance), not a silent
      // swallow ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â wait for the async mirror to settle first.
      await Future<void>.delayed(Duration.zero);
      expect(ChatStore.isDeliveryFailed(bubbles.first.id), isTrue);

      // Connectivity returns: retry lands the SAME bubble, no duplicate.
      when(() => persister.call(any())).thenAnswer((_) async => true);
      expect(await ChatStore.retryDelivery(bubbles.first.id), isTrue);
      expect(ChatStore.forRequest('req-err'), hasLength(1));
      expect(ChatStore.isDeliveryFailed(bubbles.first.id), isFalse);
      // persister is invoked TWICE total: once by the fire-and-forget send()
      // (which throws here, then is flagged undelivered) and once by the retry
      // above (which succeeds and clears the flag). mocktail counts ALL
      // invocations on the mock, so called(2) reflects the full lifecycle.
      verify(() => persister.call(any())).called(2);
    });

    test(
        'a backend REFUSAL (RLS/constraint ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ false, no throw) is flagged for '
        'retry too', () async {
      final persister = _MockInsertGateway();
      ChatStore.insertMessageGateway = persister.call;
      when(() => persister.call(any())).thenAnswer((_) async => false);

      await _openChat('req-refused');
      ChatStore.send(
        requestId: 'req-refused',
        senderId: 'client-uuid',
        senderName: 'Feres',
        text: 'salam',
        isCustomer: true,
      );
      await Future<void>.delayed(Duration.zero);

      final bubbles = ChatStore.forRequest('req-refused');
      expect(bubbles, hasLength(1));
      expect(ChatStore.isDeliveryFailed(bubbles.first.id), isTrue);
      verify(() => persister.call(any())).called(1);
    });

    test(
        'OFFLINE with no backend: the local bubble is NOT flagged undelivered '
        '(local-first is the contract, not a failure)', () async {
      ConnectivityStore.debugSetOnline(false);
      ChatStore.insertMessageGateway = (message) async => true;

      await _openChat('req-offline');
      ChatStore.send(
        requestId: 'req-offline',
        senderId: 'client-uuid',
        senderName: 'Feres',
        text: 'salam',
        isCustomer: true,
      );
      await Future<void>.delayed(Duration.zero);

      final bubbles = ChatStore.forRequest('req-offline');
      expect(bubbles, hasLength(1));
      expect(ChatStore.isDeliveryFailed(bubbles.first.id), isFalse);
    });

    test(
        'a failed media upload is NOT stranded: retry re-uploads and lands',
        () async {
      final persister = _MockInsertGateway();
      ChatStore.insertMessageGateway = persister.call;
      when(() => persister.call(any())).thenAnswer((_) async => true);
      final uploader = _MockUploadGateway();
      ChatStore.uploadMediaGateway = uploader.call;

      await _openChat('req-media-retry');
      // First attempt: Storage unreachable → null → bubble stays flagged.
      when(() => uploader.call(any(), any(), any()))
          .thenAnswer((_) async => null);
      ChatStore.sendVoice(
        requestId: 'req-media-retry',
        senderId: 'client-uuid',
        senderName: 'Feres',
        filePath: '/data/user/0/voice/note.m4a',
        durationSec: 9,
        isCustomer: true,
      );
      await Future<void>.delayed(Duration.zero);

      final bubbles = ChatStore.forRequest('req-media-retry');
      expect(bubbles, hasLength(1));
      expect(ChatStore.isDeliveryFailed(bubbles.first.id), isTrue);
      expect(bubbles.first.mediaPath, '/data/user/0/voice/note.m4a');
      // Local path never reaches the shared table.
      verifyNever(() => persister.call(any()));

      // Connectivity returns: the SAME retry re-uploads, swaps the bubble to
      // the public URL, then mirrors the row — no duplicate bubble.
      const remoteUrl = 'https://cdn.example/req-media-retry/voice_1.m4a';
      when(() => uploader.call(any(), any(), any()))
          .thenAnswer((_) async => remoteUrl);
      expect(await ChatStore.retryDelivery(bubbles.first.id), isTrue);

      final landed = ChatStore.forRequest('req-media-retry');
      expect(landed, hasLength(1));
      expect(landed.single.mediaPath, remoteUrl);
      expect(ChatStore.isDeliveryFailed(bubbles.first.id), isFalse);
      // The mirrored row carries the remote URL, never the device path.
      final captured = verify(() => persister.call(captureAny()))
          .captured
          .single as ChatMessage;
      expect(captured.id, bubbles.first.id);
      expect(captured.mediaPath, remoteUrl);
    });
  });
